import GiftUIInteraction
import GiftUISemanticCore
func accept<G, C, R, H>(owner: consuming CyclePipelineOwner<G, C, R, H>) where G: CycleGeometry, C: InteractionCandidateRecordStorage, R: InteractionCommittedRecordStorage, H: InteractionHitRegionStorage, C.Identity == SemanticCompleteIdentity, R.Identity == SemanticCompleteIdentity, H.Identity == SemanticCompleteIdentity {}
func check<G, C, R, H>(owner: consuming CyclePipelineOwner<G, C, R, H>) where G: CycleGeometry, C: InteractionCandidateRecordStorage, R: InteractionCommittedRecordStorage, H: InteractionHitRegionStorage, C.Identity == SemanticCompleteIdentity, R.Identity == SemanticCompleteIdentity, H.Identity == SemanticCompleteIdentity {
    accept(owner: consume owner)
    _ = owner.benchBackingEvidence()
}
